from __future__ import annotations

import json
import subprocess
from pathlib import Path

from typer.testing import CliRunner

from monitor_opportunities.cli import app

runner = CliRunner()


def test_decision_idempotency_and_replay(tmp_path: Path) -> None:
    run_dir = tmp_path / "run"
    args = [
        "decision",
        "--run",
        str(run_dir),
        "--item",
        "opp:a",
        "--action",
        "KEEP",
        "--idempotency-key",
        "same-key",
    ]
    first = runner.invoke(app, args)
    second = runner.invoke(app, args)
    assert first.exit_code == 0, first.output
    assert second.exit_code == 0, second.output
    ledger_rows = [
        json.loads(line)
        for line in (run_dir / "decision-ledger.jsonl").read_text(encoding="utf-8").splitlines()
        if line
    ]
    assert len(ledger_rows) == 1
    assert ledger_rows[0]["run_id"] == str(run_dir)
    assert ledger_rows[0]["prior_report_digest"] is None
    assert ledger_rows[0]["artifact_hashes"] == {"item_digest": None}
    assert ledger_rows[0]["resulting_state"] == "KEPT"
    assert ledger_rows[0]["external_effects"] is False
    replay = runner.invoke(app, ["replay", "--run", str(run_dir)])
    assert replay.exit_code == 0, replay.output
    projection = json.loads((run_dir / "decision-projection.json").read_text(encoding="utf-8"))
    assert projection["items"]["opp:a"]["last_action"] == "KEEP"
    assert projection["items"]["opp:a"]["resulting_state"] == "KEPT"
    assert projection["external_effects"] is False
    replay_payload = json.loads(replay.output)
    replay_receipt_path = Path(replay_payload["zero_effect_replay_path"])
    assert replay_receipt_path.is_file()
    replay_receipt = json.loads(replay_receipt_path.read_text(encoding="utf-8"))
    assert replay_receipt["schema"] == "monitor_opportunities.zero_effect_replay_receipt.v1"
    assert replay_receipt["status"] == "PASS"
    assert replay_receipt["checks"]["projection_external_effects_false"] is True
    assert replay_receipt["checks"]["decision_events_external_effects_false"] is True
    assert replay_receipt["external_effects"] is False


def test_human_sent_markers_require_explicit_human_actor(tmp_path: Path) -> None:
    run_dir = tmp_path / "run"
    default_actor = runner.invoke(
        app,
        [
            "decision",
            "--run",
            str(run_dir),
            "--item",
            "packet:gmail",
            "--action",
            "MARK_HUMAN_SENT_GMAIL",
            "--idempotency-key",
            "gmail-default",
        ],
    )
    assert default_actor.exit_code == 2
    assert "requires explicit human actor" in default_actor.stderr
    human_actor = runner.invoke(
        app,
        [
            "decision",
            "--run",
            str(run_dir),
            "--item",
            "packet:gmail",
            "--action",
            "MARK_HUMAN_SENT_GMAIL",
            "--actor",
            "human",
            "--idempotency-key",
            "gmail-human",
        ],
    )
    assert human_actor.exit_code == 0, human_actor.output
    ledger_rows = [
        json.loads(line)
        for line in (run_dir / "decision-ledger.jsonl").read_text(encoding="utf-8").splitlines()
        if line
    ]
    assert len(ledger_rows) == 1
    assert ledger_rows[0]["actor"] == "human"
    assert ledger_rows[0]["external_effects"] is False


def test_replay_rejects_external_effect_ledger_row(tmp_path: Path, monkeypatch) -> None:
    run_dir = tmp_path / "run"
    run_dir.mkdir(parents=True)
    (run_dir / "decision-ledger.jsonl").write_text(
        json.dumps(
            {
                "schema": "monitor_opportunities.decision_event.v1",
                "event_id": "decision:poisoned",
                "run_id": str(run_dir),
                "run_dir": str(run_dir),
                "item_id": "opp:poisoned",
                "action": "KEEP",
                "actor": "agent",
                "created_at": "2026-08-15T00:00:00Z",
                "payload_digest": "digest",
                "resulting_state": "KEPT",
                "external_effects": True,
            },
            sort_keys=True,
        )
        + "\n",
        encoding="utf-8",
    )

    def fail_on_subprocess(*_args, **_kwargs):
        raise AssertionError("replay must not call external subprocess adapters")

    monkeypatch.setattr(subprocess, "run", fail_on_subprocess)

    replay = runner.invoke(app, ["replay", "--run", str(run_dir)])

    assert replay.exit_code == 2
    assert "ZERO_EFFECT_REPLAY_FAILED" in replay.stderr
    replay_receipt = json.loads(
        (run_dir / "zero-effect-replay-receipt.json").read_text(encoding="utf-8")
    )
    assert replay_receipt["status"] == "FAIL"
    assert replay_receipt["checks"]["decision_events_external_effects_false"] is False
    assert replay_receipt["violations"]["decision_event_external_effects"] == ["decision:poisoned"]
